from pathlib import Path
from PIL import Image,ImageDraw
import json,subprocess
R=Path(__file__).resolve().parents[1];review=R/'review'
for label in ['before','after']:
 d=review/label;m=json.loads((d/'metadata.json').read_text());assert m['frames']==list(range(0,157,2))
 lines=[]
 for f in m['frames']:lines += ["file '"+str((d/f'f{f:04d}.png').resolve()).replace('\\','/')+"'",'duration '+str(1/6)]
 lines += ["file '"+str((d/'f0156.png').resolve()).replace('\\','/')+"'"]
 manifest=review/f'{label}-concat.txt';manifest.write_text('\n'.join(lines))
 subprocess.run(['ffmpeg','-y','-hide_banner','-loglevel','error','-f','concat','-safe','0','-i',str(manifest),'-t',str(157/12),'-r','24','-c:v','libx264','-crf','19','-pix_fmt','yuv420p','-movflags','+faststart',str(review/f'{label}.mp4')],check=True)
frames=[0,24,48,72,100,138]
canvas=Image.new('RGB',(1280,384*len(frames)),(23,27,32));draw=ImageDraw.Draw(canvas)
for row,f in enumerate(frames):
 for col,label in enumerate(['before','after']):
  canvas.paste(Image.open(review/label/f'f{f:04d}.png'),(col*640,row*384+24));draw.text((col*640+10,row*384+6),f'{label.upper()} / f{f}',fill='white')
canvas.save(review/'comparison.jpg',quality=92)
html='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>첫 프레임 인양 줄 길이 수정 비교</title><style>body{background:#111820;color:#eaf2f7;font:16px system-ui;margin:32px auto;max-width:1420px;padding:0 24px}h1{font-size:28px}p{line-height:1.7;color:#c4d3df}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}video,img{width:100%;background:#080d12;border-radius:10px}button,select,a.btn{background:#254554;color:white;border:1px solid #486773;padding:10px 16px;border-radius:7px;margin:4px;cursor:pointer}a{color:#73d7eb}.path{overflow-wrap:anywhere}label{display:block;margin:12px 0}footer{margin:30px 0;color:#a2b6c2}@media(max-width:800px){.grid{grid-template-columns:1fr}}</style><h1>첫 프레임 인양 줄 길이 수정</h1><p>첫 프레임의 줄 길이 <b>70cm → 20cm</b> · 컨테이너 시작점 <b>50cm 추가 상승</b>.<br>카메라와 크레인 높이는 그대로입니다. 컨테이너가 크레인에 더 가까이 붙은 상태에서 출발하며 기존 f72 안착으로 이어집니다.</p><button id="play">처음부터 동시 재생</button><button id="pause">일시 정지</button><select id="speed" aria-label="재생 속도"><option value="1">실제 시간 1×</option><option value="2">2×</option><option value="3.5">3.5×</option></select><div class="grid"><section><h2>수정 전</h2><video id="before" src="review/before.mp4" poster="review/before/f0000.png" controls muted playsinline></video></section><section><h2>수정 후</h2><video id="after" src="review/after.mp4" poster="review/after/f0000.png" controls muted playsinline></video></section></div><p>f0–156 · 원본 12fps 시간축 · 2프레임 간격 프리뷰. 속도 선택은 이 페이지의 재생에만 적용됩니다.</p><h2>같은 프레임 비교</h2><div id="frames"></div><div class="grid"><img id="stillBefore" alt="수정 전 프레임" src="review/before/f0000.png"><img id="stillAfter" alt="수정 후 프레임" src="review/after/f0000.png"></div><h2>수정된 Blender 파일</h2><p class="path"><a href="master-previz-crane-height-v002.blend">master-previz-crane-height-v002.blend</a><br>F:\\pnpline-landing\\hero-section-video\\blockout\\previz-crane-height-v002\\master-previz-crane-height-v002.blend</p><p id="validation">검증 결과를 정리 중입니다.</p><footer>원본 저장본은 inputs/base.blend에 보존했습니다.</footer><script>const videos=[document.querySelector('#before'),document.querySelector('#after')];document.querySelector('#play').onclick=()=>videos.forEach(v=>{v.currentTime=0;v.play()});document.querySelector('#pause').onclick=()=>videos.forEach(v=>v.pause());document.querySelector('#speed').onchange=e=>videos.forEach(v=>v.playbackRate=+e.target.value);for(const f of [0,24,48,72,100,138,156]){const b=document.createElement('button');b.textContent='f'+f;b.onclick=()=>{const n=String(f).padStart(4,'0');document.querySelector('#stillBefore').src='review/before/f'+n+'.png';document.querySelector('#stillAfter').src='review/after/f'+n+'.png';videos.forEach(v=>{v.pause();v.currentTime=f/12})};document.querySelector('#frames').append(b)}fetch('verification-summary.json').then(r=>r.json()).then(r=>{document.querySelector('#validation').textContent=r.pass?'검증 통과: 줄 연결·인양 장치 간섭·내부 화물·카메라 및 안착 이후 동작 보존. 자세한 결과는 verification-summary.json에 기록했습니다.':'검증 진행 중'}).catch(()=>{});</script></html>'''
(R/'review.html').write_text(html,encoding='utf-8')
print('PACKAGED',R/'review.html')
